begin;
set local search_path=public,extensions;
select plan(41);
grant usage on schema extensions to authenticated;
grant execute on all functions in schema extensions to authenticated;

select ok((select count(*)=9 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['dispute_cases','dispute_evidence','dispute_responses','dispute_decisions','dispute_financial_consequences','provider_performance_events','mission_reassignments','dispute_appeals','dispute_case_events'])),'all dispute, evidence, consequence, appeal and reassignment tables exist');
select ok((select count(*)=9 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['dispute_cases','dispute_evidence','dispute_responses','dispute_decisions','dispute_financial_consequences','provider_performance_events','mission_reassignments','dispute_appeals','dispute_case_events'])),'RLS is enabled on every dispute table');
select ok((select count(*)=10 and count(distinct tablename)=9 from pg_policies where schemaname='public'and tablename=any(array['dispute_cases','dispute_evidence','dispute_responses','dispute_decisions','dispute_financial_consequences','provider_performance_events','mission_reassignments','dispute_appeals','dispute_case_events'])) and exists(select 1 from pg_policies where schemaname='public' and policyname='dispute_cases_franchise_library_read' and qual like '%franchise_supervises_dispute%'),'each dispute table has an explicit scoped read policy');
select ok((select count(*)=7 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['open_mission_dispute','respond_to_mission_dispute','decide_mission_dispute','appeal_mission_dispute','propose_mission_reassignment','approve_reassignment_cost','activate_mission_reassignment'])),'seven public commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['open_mission_dispute','respond_to_mission_dispute','decide_mission_dispute','appeal_mission_dispute','propose_mission_reassignment','approve_reassignment_cost','activate_mission_reassignment'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anonymous and service roles cannot execute user dispute commands');
select ok((select count(*)=7 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['open_mission_dispute','respond_to_mission_dispute','decide_mission_dispute','appeal_mission_dispute','propose_mission_reassignment','approve_reassignment_cost','activate_mission_reassignment'])),'authenticated users have only explicit command execution');
select ok(not has_table_privilege('authenticated','public.dispute_cases','INSERT')and not has_table_privilege('authenticated','public.dispute_decisions','UPDATE')and not has_table_privilege('authenticated','public.mission_reassignments','UPDATE'),'direct case, decision and reassignment mutation is denied');
select ok(not has_table_privilege('authenticated','public.dispute_evidence','INSERT')and not has_table_privilege('authenticated','public.dispute_financial_consequences','DELETE'),'direct evidence and financial consequence mutation is denied');
select ok((select count(*)=7 from pg_trigger where tgname=any(array['dispute_evidence_immutable','dispute_responses_immutable','dispute_decisions_immutable','dispute_consequences_immutable','provider_performance_events_immutable','dispute_appeals_immutable','dispute_case_events_immutable'])and not tgisinternal),'evidence, responses, decisions, consequences, appeals and history are immutable');
select ok((select data_type='bigint'from information_schema.columns where table_schema='public'and table_name='dispute_financial_consequences'and column_name='amount_minor'),'all dispute money is represented in exact minor units');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name in('dispute_financial_consequences','mission_reassignments')and data_type in('real','double precision')),'no floating-point financial column exists');
select ok((select count(*)=4 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname in('dispute_case_access','dispute_evidence_access','dispute_financial_access','dispute_reassignment_access')and p.prosecdef),'case, evidence, financial and reassignment access use protected security-definer predicates');
select ok((select pg_get_functiondef(p.oid)like'%DISPUTE_MANAGER%'and pg_get_functiondef(p.oid)like'%BOTH_PARTIES%'and pg_get_functiondef(p.oid)like'%CLIENT_ONLY%'and pg_get_functiondef(p.oid)like'%PROVIDER_ONLY%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='dispute_evidence_access'),'evidence visibility separates mediator and both parties');
with chain as(select
 pg_get_functiondef('public.open_mission_dispute(uuid,text,text,text,jsonb,jsonb,text,uuid)'::regprocedure)as wrapper,
 pg_get_functiondef('public.open_mission_dispute_legacy_client_0220(uuid,text,text,text,jsonb,jsonb,text,uuid)'::regprocedure)as primitive)
select ok(wrapper like '%auth.jwt()->>''aal''is distinct from''aal2''%'and wrapper like '%CLIENT_OWNER%'and wrapper like '%private.client_contract_dispute_policy_v1(m.contract_version_id)%'and wrapper like '%private.canonical_client_dispute_evidence_v1(m.client_organization_id,p_evidence)%'and wrapper like '%public.open_mission_dispute_legacy_client_0220(m.id,p_obligation_key,p_description,p_urgency,policy,evidence,p_idempotency_key,p_correlation_id)%'
 and primitive like '%WARNING_LEVEL_1%'and primitive like '%jsonb_array_length(p_evidence)=0%'and primitive like '%public.audit_events%'and primitive like '%public.event_outbox%'and primitive like '%DisputeWarningIssuedV1%','opening canonicalizes approved contract policy and evidence before the protected warning/audit/Outbox primitive')from chain;
with chain as(select
 pg_get_functiondef('public.respond_to_mission_dispute(uuid,text,text,jsonb,text,uuid)'::regprocedure)as wrapper,
 pg_get_functiondef('public.respond_to_mission_dispute_legacy_0441(uuid,text,text,jsonb,text,uuid)'::regprocedure)as primitive)
select ok(wrapper like '%perform private.dispute_evidence_party_v1(p_dispute_case_id,org)%'and wrapper like '%private.canonical_party_dispute_evidence_v1(p_dispute_case_id,org,p_evidence)%'and wrapper like '%public.respond_to_mission_dispute_legacy_0441(p_dispute_case_id,p_response_type,p_statement,canonical,p_idempotency_key,p_correlation_id)%'
 and primitive like '%PROVIDER_OWNER%'and primitive like '%MEDIATION_REVIEW%'and primitive like '%STALE_DISPUTE_STATE%'and primitive like '%review_due_at=private.dispute_business_deadline_v1(%'and primitive like '%correction_due_at=case when p_response_type=''ACKNOWLEDGE_AND_CORRECT''then private.dispute_business_deadline_v1(%'and primitive like '%row_version=row_version+1%'and primitive like '%public.audit_events%'and primitive like '%DisputeResponseSubmittedV1%','response canonicalizes party evidence and preserves provider scope, business deadlines, state guard, audit and Outbox')from chain;
select ok((select pg_get_functiondef(p.oid)like'%DISPUTE_MANAGER%'and pg_get_functiondef(p.oid)like'%DISPUTE_DECISION_DENIED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_mission_dispute'),'only an authorized human dispute manager can decide');
-- Structural guards complement the native governed-fixture regression in 0356.
-- The old caller-supplied validated_clause flag is no longer economic authority.
with command as(select pg_get_functiondef('public.decide_mission_dispute(uuid,text,text,uuid[],jsonb,text,uuid)'::regprocedure)as definition)
select ok(definition like '%private.resolve_contract_dispute_economics_v1(d.contract_version_id,d.obligation_key)%'and definition like '%p_rule_snapshot:=economic_rule||jsonb_build_object%'and definition not like '%validated_clause%'and definition like '%pen:=(economic->>''penalty_minor'')::bigint%'and definition like '%com:=(economic->>''commission_minor'')::bigint%','decision replaces caller economics with canonical signed-contract amounts')from command;
with resolver as(select pg_get_functiondef('private.resolve_contract_dispute_economics_v1(uuid,text)'::regprocedure)as definition)
select ok(definition like '%private.contract_version_dispute_signature_valid_v1(v.contract_id,v.id)%'and definition like '%decided_by<>t.created_by%'and definition like '%content_hash=t.content_hash%'and definition like '%is distinct from t.data->''clauses''%'and definition like '%approval.decided_at>sealed_at%','economic resolver requires genuine signature evidence and exact independently approved clauses before signing')from resolver;
with resolver as(select pg_get_functiondef('private.resolve_contract_dispute_economics_v1(uuid,text)'::regprocedure)as definition)
select ok(definition like '%item_key=p_obligation_key%'and definition like '%terms:=economics#>array[''obligations'',p_obligation_key]%'and definition like '%economics->>''currency''is distinct from v.currency%'and definition like '%9223372036854775807%'and definition like '%''penalty_beneficiary'',''CLIENT''%'and definition like '%''commission_beneficiary'',''MATRICIA''%','economic resolver binds exact bigint amounts, currency and beneficiaries to the signed obligation')from resolver;
select ok((select count(*)=2 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=%'and not has_function_privilege('anon',p.oid,'EXECUTE')and not has_function_privilege('authenticated',p.oid,'EXECUTE')and not has_function_privilege('service_role',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname in('resolve_contract_dispute_economics_v1','contract_version_dispute_signature_valid_v1')),'economic authority helpers have fixed search paths and no direct user or service execution');
with command as(select pg_get_functiondef('public.decide_mission_dispute(uuid,text,text,uuid[],jsonb,text,uuid)'::regprocedure)as definition)
select ok(definition like '%if economic is not null then%'and definition like '%APPROVED_SIGNED_ECONOMIC_RULE_REQUIRED%'and definition like '%provider_billing_exceptions_v1%'and definition not like '%VALIDATED_CONTRACT_RULE_REQUIRED%','absent signed economics records an explicit billing exception instead of trusting browser money or blocking the human finding')from command;
with command as(select pg_get_functiondef('public.decide_mission_dispute(uuid,text,text,uuid[],jsonb,text,uuid)'::regprocedure)as definition)
select ok(definition like '%auth.jwt()->>''aal''is distinct from''aal2''%'and definition like '%private.is_active_org_member(d.client_organization_id,a)%'and definition like '%private.is_active_org_member(d.provider_organization_id,a)%'and definition like '%private.has_platform_role(array[''SUPER_ADMIN'',''MATRICIA_ADMIN'',''DISPUTE_MANAGER''],a)%','decision retains AAL2 and authorized human independence from both parties')from command;
with command as(select pg_get_functiondef('public.decide_mission_dispute(uuid,text,text,uuid[],jsonb,text,uuid)'::regprocedure)as definition)
select ok(definition like '%if p_outcome=''NON_COMPLIANT_CONFIRMED''and(prior.id is null or prior.outcome is distinct from''NON_COMPLIANT_CONFIRMED'')then%','first noncompliance on appeal applies canonical effects while repeated noncompliance does not duplicate them')from command;
with command as(select pg_get_functiondef('public.decide_mission_dispute(uuid,text,text,uuid[],jsonb,text,uuid)'::regprocedure)as definition)
select ok(strpos(definition,'private.begin_contract_command')>0 and strpos(definition,'if r is not null then return r;end if;')>strpos(definition,'private.begin_contract_command')and strpos(definition,'if r is not null then return r;end if;')<strpos(definition,'raise exception ''STALE_DISPUTE_STATE'''),'idempotent receipt replay precedes the lifecycle guard so a closed decision can be retried safely')from command;
select ok((select pg_get_functiondef(p.oid)like'%CONTRACTUAL_PENALTY%'and pg_get_functiondef(p.oid)like'%MATRICIA_COMMISSION%'and pg_get_functiondef(p.oid)like'%NON_COMPLIANCE_CONFIRMED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_mission_dispute'),'confirmed non-compliance creates penalty, commission and performance evidence atomically');
select ok((select pg_get_functiondef(p.oid)like'%status=''CANCELLED''%'and pg_get_functiondef(p.oid)like'%mission_reassignments%'and pg_get_functiondef(p.oid)like'%DisputeNonComplianceConfirmedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_mission_dispute'),'confirmed non-compliance retires the source assignment, creates R1 and emits Outbox');
select ok((select pg_get_functiondef(p.oid)like'%REVERSAL%'and pg_get_functiondef(p.oid)like'%NON_COMPLIANCE_REVERSED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_mission_dispute'),'appeal reversal appends compensating records instead of mutating financial history');
with chain as(select
 pg_get_functiondef('public.appeal_mission_dispute(uuid,text,jsonb,text,uuid)'::regprocedure)as wrapper,
 pg_get_functiondef('public.appeal_mission_dispute_legacy_0441(uuid,text,jsonb,text,uuid)'::regprocedure)as primitive)
select ok(wrapper like '%org:=private.dispute_evidence_party_v1(%'and wrapper like '%private.canonical_party_dispute_evidence_v1(p_dispute_case_id,org,p_evidence)%'and wrapper like '%public.appeal_mission_dispute_legacy_0441(p_dispute_case_id,p_grounds,canonical,p_idempotency_key,p_correlation_id)%'
 and primitive like '%d.appeal_due_at is null or clock_timestamp()>d.appeal_due_at%'and primitive like '%org:=private.dispute_evidence_party_v1(%'and primitive like '%where id=d.id and status=''DECIDED''%'and primitive like '%STALE_DISPUTE_STATE%'and primitive like '%public.dispute_appeals%'and primitive like '%private.append_dispute_evidence%'and primitive like '%public.audit_events%'and primitive like '%public.event_outbox%'and primitive like '%DisputeAppealedV1%','appeal canonicalizes authorized contradictory evidence while the protected primitive enforces deadline, CAS, audit and Outbox')from chain;
with wrappers as(select pg_get_functiondef(p.oid)as definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('respond_to_mission_dispute','appeal_mission_dispute'))
select ok(count(*)=2 and bool_and(strpos(definition,'private.dispute_evidence_party_v1(')>0
 and strpos(definition,'private.dispute_evidence_party_v1(')<strpos(definition,'private.begin_contract_command(')
 and strpos(definition,'private.begin_contract_command(')<strpos(definition,'if cached is not null then return cached;end if;')
 and strpos(definition,'if cached is not null then return cached;end if;')<strpos(definition,'canonical:=private.canonical_party_dispute_evidence_v1(')
 and strpos(definition,'canonical:=private.canonical_party_dispute_evidence_v1(')<strpos(definition,'result:=public.')
 and definition like '%private.finish_contract_command(client_org,scope,p_idempotency_key,result)%'),'response and appeal authorize the current party then replay their receipt before canonicalizing evidence or changing state')from wrappers;
select ok((select count(*)=3 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=%'and not has_function_privilege('anon',p.oid,'EXECUTE')and not has_function_privilege('authenticated',p.oid,'EXECUTE')and not has_function_privilege('service_role',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('open_mission_dispute_legacy_client_0220','respond_to_mission_dispute_legacy_0441','appeal_mission_dispute_legacy_0441')),'legacy open, response and appeal primitives are protected definer functions without direct public, authenticated or service execution');
with party as(select pg_get_functiondef('private.dispute_evidence_party_v1(uuid,uuid)'::regprocedure)as definition)
select ok(definition like '%auth.uid() is null%'and definition like '%auth.jwt()->>''aal'' is distinct from ''aal2''%'and definition like '%p_org=d.client_organization_id%'and definition like '%p_org=d.provider_organization_id%'and definition like '%private.has_org_role(d.client_organization_id,array[''CLIENT_OWNER'',''CLIENT_ADMIN''])%'and definition like '%private.has_org_role(d.provider_organization_id,array[''PROVIDER_OWNER'',''PROVIDER_MANAGER''])%'and definition like '%DISPUTE_EVIDENCE_DENIED%','private party resolution requires AAL2 and the selected organization role rather than an arbitrary membership')from party;
with evidence as(select pg_get_functiondef('private.canonical_party_dispute_evidence_v1(uuid,uuid,jsonb)'::regprocedure)as definition)
select ok(definition like '%perform private.dispute_evidence_party_v1(p_case,p_org)%'and definition like '%jsonb_array_length(p_items)not between 1 and 20%'and definition like '%INVALID_EVIDENCE_VISIBILITY%'and definition like '%provider_organization_id=p_org and status=''VERIFIED''%'and definition like '%private.provider_document_is_clean(doc.storage_object_path,doc.content_hash)%'and definition like '%dl.mission_id=d.mission_id%'and definition like '%s.computed_sha256=p.evidence_hash%'and definition like '%private.can_access_internal_message_thread(t.id)%','canonical evidence restricts party visibility and resolves verified clean documents, scoped messages and scanned mission proofs')from evidence;
select ok((select count(*)=2 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=%'and not has_function_privilege('anon',p.oid,'EXECUTE')and not has_function_privilege('authenticated',p.oid,'EXECUTE')and not has_function_privilege('service_role',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname in('dispute_evidence_party_v1','canonical_party_dispute_evidence_v1')),'party and canonical evidence helpers remain private with fixed search paths and closed user/service ACLs');
with primitives as(select pg_get_functiondef(p.oid)as definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('respond_to_mission_dispute_legacy_0441','appeal_mission_dispute_legacy_0441'))
select ok(count(*)=2 and bool_and(strpos(definition,'private.begin_contract_command(')>0
 and strpos(definition,'private.begin_contract_command(')<strpos(definition,'if r is not null then return r;end if;')
 and strpos(definition,'if r is not null then return r;end if;')<strpos(definition,'select * into d from public.dispute_cases where id=d.id for update;')
 and strpos(definition,'select * into d from public.dispute_cases where id=d.id for update;')<strpos(definition,'raise exception ''STALE_DISPUTE_STATE''')),'protected response and appeal primitives replay before row locking and preserve transactional state rejection')from primitives;
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_APPROVAL_REQUIRED%'and pg_get_functiondef(p.oid)like'%cost_delta_minor%'and pg_get_functiondef(p.oid)like'%FRAMEWORK_RATE%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='propose_mission_reassignment'),'replacement proposal calculates exact cost delta and gates increases');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_OWNER%'and pg_get_functiondef(p.oid)like'%REASSIGNMENT_APPROVED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='approve_reassignment_cost'),'only the client can approve a higher replacement cost');
select ok((select pg_get_functiondef(p.oid)like'%appeal_due_at%'and pg_get_functiondef(p.oid)like'%replacement_contract_id%'and pg_get_functiondef(p.oid)like'%MissionReassignedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='activate_mission_reassignment'),'activation waits for appeal safety and requires replacement contract and mission lineage');
select ok((select count(*)>=4 from pg_constraint where conrelid='public.mission_reassignments'::regclass and contype='f'),'reassignment preserves source, root, dispute and replacement lineage with foreign keys');
select ok((select is_generated='ALWAYS'from information_schema.columns where table_schema='public'and table_name='mission_reassignments'and column_name='reassignment_key'),'R1/R2 labels are derived from the immutable sequence number');
select ok((select count(*)>=7 from pg_indexes where schemaname='public'and tablename=any(array['dispute_cases','dispute_evidence','dispute_decisions','dispute_case_events','mission_reassignments'])),'case, deadline, evidence, decision and reassignment access paths are indexed');
select ok((select count(*)=1 from pg_constraint where conrelid='public.dispute_financial_consequences'::regclass and contype='u'and pg_get_constraintdef(oid)like'%consequence_type%'and pg_get_constraintdef(oid)like'%direction%'),'retries cannot duplicate a penalty, commission or reversal');

select * from finish();
rollback;
